parley.ordering.par:
to first_item with left_time as number, left_id as number, right_time as number, right_id as number giving number:
    if left_time is less than right_time:
        give back left_id
    if left_time is right_time:
        give back right_id
    give back right_id

python.ordering.py:
def first_item(left_time: int, left_id: int, right_time: int, right_id: int) -> int:
    if left_time < right_time:
        return left_id
    if left_time == right_time:
        return right_id
    return right_id

rust.ordering.rs:
pub fn first_item(left_time: i64, left_id: i64, right_time: i64, right_id: i64) -> i64 {
    if left_time < right_time { return left_id; }
    if left_time == right_time { return right_id; }
    right_id
}

rust.page.rs:
pub fn second_item(first: i64, left_id: i64, right_id: i64) -> i64 {
    if first == left_id { right_id } else { left_id }
}

rust.formatting.rs:
pub fn format_page(first: i64, second: i64, cursor: i64) -> String {
    format!("first={first}|second={second}|cursor={cursor}")
}

rust.main.rs:
mod cursor;
mod formatting;
mod ordering;
